export function subtaskCall(title: string, taskId = MAIL_TASK_ID): DeferredCall {
  return {
    tool: "create_subtask",
    args: { taskId, title },
    label: `Добавить подзадачу «${title}» в «${MAIL_TASK}»`,
  };
}

export function taskCall(title: string): DeferredCall {
  return { tool: "create_task", args: { title, columnId: "col-backlog" }, label: `Задача «${title}»` };
}

export const A_CALLS = A_TITLES.map((t) => subtaskCall(t));
export const B_CALLS = B_TITLES.map(taskCall);
/** Итог слияния: все восемь — подзадачами одной задачи. */
export const MERGED_CALLS = [...A_TITLES, ...B_TITLES].map((t) => subtaskCall(t));
